package ru.aeroclub.informer;
import android.content.ContentValues;import android.content.Context;import android.content.SharedPreferences;import android.database.Cursor;import android.net.Uri;import android.os.Build;import android.os.Environment;import android.provider.MediaStore;
import org.json.JSONArray;import org.json.JSONObject;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.HashSet;import java.util.Set;
/** Versioned automatic JSON exchange for flight records in Android Downloads. */
public final class FlightDownloadExchange {
 public static final String FILE_NAME="Aeroclub_Informer_flights.json";private static final String FORMAT="aeroclub-flights";private static final int VERSION=1,MAX_BYTES=2*1024*1024;private static final String HASH_KEY="aeroclub_download_flights_sha256";private static final Object LOCK=new Object();private FlightDownloadExchange(){}
 public static String getPath(){return "Download/"+FILE_NAME;}
 public static boolean importIfChanged(Context c,SharedPreferences p,String flightsKey,String activeKey){if(c==null||p==null)return false;synchronized(LOCK){try{
  Uri uri=findExisting(c);if(uri==null)return false;byte[] bytes=readBytes(c,uri);if(bytes.length==0)return invalid(c,"empty_file");String hash=sha256(bytes);if(hash.equals(p.getString(HASH_KEY,"")))return false;
  JSONObject root=new JSONObject(new String(bytes,StandardCharsets.UTF_8));if(!FORMAT.equals(root.optString("format"))||root.optInt("version",-1)!=VERSION)return invalid(c,"unsupported_schema");
  JSONArray arr=root.optJSONArray("flights");if(arr==null||arr.length()==0)return invalid(c,"missing_flights");Set<String> ids=new HashSet<>();JSONArray normalized=new JSONArray();String active=root.optString("activeFlightId","");boolean activeFound=false;
  for(int i=0;i<arr.length();i++){JSONObject f=arr.optJSONObject(i);if(f==null)return invalid(c,"invalid_flight_record");String id=f.optString("id","").trim(),title=f.optString("title","").trim(),iso=FlightDateUtils.toIso(f.optString("dateIso","")),time=f.optString("time","").trim();
   if(id.isEmpty()||title.isEmpty()||iso.isEmpty()||!FlightDateUtils.isValidTime(time)||!ids.add(id))return invalid(c,"invalid_or_duplicate_flight");if(id.equals(active))activeFound=true;
   JSONObject item=new JSONObject(f.toString());item.put("dateIso",iso);item.put("date",f.optString("date",FlightDateUtils.toDisplay(iso)));item.put("isDemo",false);normalized.put(item);}
  if(!activeFound)active=arr.getJSONObject(0).optString("id");p.edit().putString(flightsKey,normalized.toString()).putString(activeKey,active).putString(HASH_KEY,hash).apply();log(c,"import","success","count="+arr.length());return true;
 }catch(Exception e){log(c,"import","error",e.getClass().getSimpleName());return false;}}}
 public static boolean publish(Context c,SharedPreferences p,String flightsKey,String activeKey){if(c==null||p==null)return false;synchronized(LOCK){try{
  JSONArray arr=new JSONArray(p.getString(flightsKey,"[]"));JSONObject root=new JSONObject();root.put("format",FORMAT);root.put("version",VERSION);root.put("updatedAt",System.currentTimeMillis());root.put("activeFlightId",p.getString(activeKey,""));root.put("flights",arr);byte[] bytes=root.toString(2).getBytes(StandardCharsets.UTF_8);if(bytes.length>MAX_BYTES)return fail(c,"flight_file_over_2MiB");
  Uri uri=findOrCreate(c);if(uri==null)return fail(c,"downloads_unavailable");if("file".equals(uri.getScheme())){File file=new File(uri.getPath()),parent=file.getParentFile();if(parent!=null&&!parent.isDirectory()&&!parent.mkdirs())return fail(c,"mkdir_failed");File temp=new File(parent,FILE_NAME+".tmp");try(FileOutputStream out=new FileOutputStream(temp,false)){out.write(bytes);out.flush();out.getFD().sync();}if(file.exists()&&!file.delete())return fail(c,"replace_failed");if(!temp.renameTo(file))return fail(c,"rename_failed");}
  else try(OutputStream out=c.getContentResolver().openOutputStream(uri,"wt")){if(out==null)return fail(c,"open_output_failed");out.write(bytes);out.flush();}
  p.edit().putString(HASH_KEY,sha256(bytes)).apply();log(c,"export","success","count="+arr.length());return true;
 }catch(Exception e){log(c,"export","error",e.getClass().getSimpleName());return false;}}}
 private static boolean invalid(Context c,String s){log(c,"import","error",s);return false;}private static boolean fail(Context c,String s){log(c,"export","error",s);return false;}
 private static Uri findExisting(Context c){if(Build.VERSION.SDK_INT>=29){Uri col=MediaStore.Downloads.EXTERNAL_CONTENT_URI;String sel=MediaStore.Downloads.DISPLAY_NAME+"=? AND "+MediaStore.Downloads.RELATIVE_PATH+"=?";try(Cursor cur=c.getContentResolver().query(col,new String[]{MediaStore.Downloads._ID},sel,new String[]{FILE_NAME,Environment.DIRECTORY_DOWNLOADS+"/"},null)){if(cur!=null&&cur.moveToFirst())return Uri.withAppendedPath(col,cur.getString(0));}return null;}File f=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS),FILE_NAME);return f.isFile()?Uri.fromFile(f):null;}
 private static Uri findOrCreate(Context c){Uri old=findExisting(c);if(old!=null)return old;if(Build.VERSION.SDK_INT<29)return Uri.fromFile(new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS),FILE_NAME));ContentValues v=new ContentValues();v.put(MediaStore.Downloads.DISPLAY_NAME,FILE_NAME);v.put(MediaStore.Downloads.MIME_TYPE,"application/json");v.put(MediaStore.Downloads.RELATIVE_PATH,Environment.DIRECTORY_DOWNLOADS+"/");return c.getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);}
 private static byte[] readBytes(Context c,Uri uri)throws Exception{try(InputStream in="file".equals(uri.getScheme())?new FileInputStream(new File(uri.getPath())):c.getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)return new byte[0];byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>MAX_BYTES)throw new IllegalArgumentException("file_over_2MiB");out.write(buf,0,n);}return out.toByteArray();}}
 private static String sha256(byte[] b)throws Exception{byte[] d=MessageDigest.getInstance("SHA-256").digest(b);StringBuilder s=new StringBuilder();for(byte v:d)s.append(String.format(java.util.Locale.ROOT,"%02x",v&255));return s.toString();}
 private static void log(Context c,String a,String o,String d){ModuleDebugLog.log(c,"FLIGHT-FILE",a,o,d);}
}
